import{_ as a,o as i,c as n,a2 as s}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Tinkering","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/professions/tinkering.md","filePath":"es/game-design/professions/tinkering.md"}'),r={name:"es/game-design/professions/tinkering.md"};function o(t,e,l,c,d,p){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="tinkering" tabindex="-1">Tinkering <a class="header-anchor" href="#tinkering" aria-label="Enlace permanente a &quot;Tinkering&quot;">​</a></h1><p><strong>Estado del diseño:</strong> Propuesto; todas las mecánicas, ejemplos y caminos técnicos siguientes siguen siendo candidatos. <strong>Implementación:</strong> este lote documental no establece ninguna implementación del rediseño. <strong>Disponibilidad:</strong> no establecida. <strong>Verificación:</strong> solo revisión documental; sin prueba de juego. <strong>Revisado:</strong> 2026-10-09 para la versión pública; se conservan el estado del diseño y las mecánicas de la especificación canónica.</p><p><a href="/Syrolands-Public/es/guide/professions/tinkering.html">Resumen para jugadores</a> · <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a></p><h2 id="purpose-and-profession-loop" tabindex="-1">Propósito y ciclo profesional <a class="header-anchor" href="#purpose-and-profession-loop" aria-label="Enlace permanente a &quot;Propósito y ciclo profesional&quot;">​</a></h2><p>Tinkering es mecánica de precisión / ingeniería / mecanismos.</p><h3 id="core-loop" tabindex="-1">Ciclo principal <a class="header-anchor" href="#core-loop" aria-label="Enlace permanente a &quot;Ciclo principal&quot;">​</a></h3><p>Inspeccionar -&gt; Diseñar -&gt; Montar -&gt; Calibrar -&gt; Probar -&gt; Mantener</p><p>Identidad: Tinkering es una profesión deliberadamente «cerebral» que sustenta muchas familias especializadas de juego.</p><h3 id="abstract-mechanism-model" tabindex="-1">Modelo abstracto de mecanismo <a class="header-anchor" href="#abstract-mechanism-model" aria-label="Enlace permanente a &quot;Modelo abstracto de mecanismo&quot;">​</a></h3><ul><li>Energía</li><li>Movimiento</li><li>Disparador</li><li>Control</li><li>Salida</li></ul><h3 id="possible-component-logic-families" tabindex="-1">Posibles familias de componentes/lógica <a class="header-anchor" href="#possible-component-logic-families" aria-label="Enlace permanente a &quot;Posibles familias de componentes/lógica&quot;">​</a></h3><p>Entradas/disparadores:</p><ul><li>interruptor;</li><li>placa de presión;</li><li>cable trampa;</li><li>temporizador;</li><li>contacto;</li><li>otros disparadores mecánicos.</li></ul><p>Lógica/control:</p><ul><li>comportamiento simple similar a AND/OR/NOT;</li><li>retardos;</li><li>contadores;</li><li>relés;</li></ul><p>pero mantenerlo deliberadamente acotado.</p><p>Salidas:</p><ul><li>puertas;</li><li>portones;</li><li>jaulas;</li><li>campanas;</li><li>comederos;</li><li>poleas;</li><li>trampas;</li><li>luces;</li><li>dispensadores;</li><li>otros mecanismos.</li></ul><h3 id="housing-automation" tabindex="-1">Automatización de viviendas <a class="header-anchor" href="#housing-automation" aria-label="Enlace permanente a &quot;Automatización de viviendas&quot;">​</a></h3><p>Tinkering debería permitir a futuro crear sistemas de lógica mecánica dentro de viviendas, conceptualmente similares a una capa limitada de redstone/puertas lógicas:</p><ul><li>un interruptor abre un portón;</li><li>un temporizador activa un comedero;</li><li>un disparador de movimiento/presión activa una alarma;</li><li>una secuencia mecánica acciona una jaula/polea;</li></ul><p>etc.</p><p>La automatización de viviendas es una propuesta futura, fuera del alcance de implementación.</p><h3 id="locks-security" tabindex="-1">Cerraduras/seguridad <a class="header-anchor" href="#locks-security" aria-label="Enlace permanente a &quot;Cerraduras/seguridad&quot;">​</a></h3><p>Tinkering puede crear e inspeccionar cerraduras/seguridad mecánica. Lockpicking las vence. Tinkering + Lockpicking aporta una comprensión más rica.</p><p>Las viviendas no tienen por qué ser mágicamente impenetrables. El futuro juego de robo puede incluir:</p><ul><li>inspeccionar cerraduras;</li><li>abrir cerraduras de puertas exteriores;</li><li>movimiento oculto/sigiloso;</li><li>Detect Hidden para trampas/alarmas;</li><li>Remove Trap/Tinkering para contramedidas;</li><li>contenedores interiores cerrados;</li><li>cuentas regresivas de alarma;</li><li>respuesta de guardias/seguridad;</li><li>riesgo creciente.</li></ul><p>El balance debe evitar abrir cerraduras AFK de forma trivial o la pérdida total de una casa.</p><h3 id="traps" tabindex="-1">Trampas <a class="header-anchor" href="#traps" aria-label="Enlace permanente a &quot;Trampas&quot;">​</a></h3><p>Combinación modular de disparador + mecanismo + salida/carga. Alchemy puede proporcionar cargas. Tinkering aporta control/entrega.</p><h3 id="reverse-engineering" tabindex="-1">Ingeniería inversa <a class="header-anchor" href="#reverse-engineering" aria-label="Enlace permanente a &quot;Ingeniería inversa&quot;">​</a></h3><ul><li>inspeccionar;</li><li>desmontar;</li><li>inferir el mecanismo;</li><li>reconstruir;</li><li>arriesgar daños;</li><li>descubrir técnicas en dispositivos del mundo.</li></ul><h3 id="dungeon-utility" tabindex="-1">Utilidad en mazmorras <a class="header-anchor" href="#dungeon-utility" aria-label="Enlace permanente a &quot;Utilidad en mazmorras&quot;">​</a></h3><ul><li>reparar mecanismos;</li><li>restaurar elevadores/puentes;</li><li>sortear sistemas mecánicos;</li><li>diagnosticar trampas;</li><li>operar maquinaria.</li></ul><h3 id="golems-mechanical-automatons" tabindex="-1">Gólems / autómatas mecánicos <a class="header-anchor" href="#golems-mechanical-automatons" aria-label="Enlace permanente a &quot;Gólems / autómatas mecánicos&quot;">​</a></h3><p>Tinkering debería admitir a futuro constructos mecánicos de alto nivel.</p><p>Posible progresión:</p><ul><li>juguetes/dispositivos simples;</li><li>autómatas utilitarios;</li><li>constructos de carga/mantenimiento;</li><li>mecanismos estacionarios;</li><li>constructos capaces de combatir;</li><li>verdaderos gólems mecánicos como especialización de alto nivel.</li></ul><p>Los constructos grandes pueden requerir colaboración:</p><ul><li>Blacksmithing para armazón/armadura;</li><li>Tinkering para movimiento/control;</li><li>Alchemy para energía/lubricantes/sistemas volátiles;</li><li>posiblemente Inscription/Magery para control/vinculación mágicos, si se acepta más adelante.</li></ul><p>Los gólems siguen siendo una dirección futura de especialización de alto nivel; el diseño detallado se pospone.</p><h2 id="knowledge-and-specialization" tabindex="-1">Conocimiento y especialización <a class="header-anchor" href="#knowledge-and-specialization" aria-label="Enlace permanente a &quot;Conocimiento y especialización&quot;">​</a></h2><p><strong>Mechanist&#39;s Journal.</strong> Los dispositivos del mundo pueden enseñar técnicas mediante inspección e ingeniería inversa arriesgada. Mecánica de precisión, seguridad y futuros constructos ofrecen identidades especializadas distintas.</p><h2 id="shared-progression-production-and-economy" tabindex="-1">Progresión, producción y economía compartidas <a class="header-anchor" href="#shared-progression-production-and-economy" aria-label="Enlace permanente a &quot;Progresión, producción y economía compartidas&quot;">​</a></h2><p>El <a href="/Syrolands-Public/es/game-design/characters/skills-and-skillcap.html">marco de habilidades del personaje</a> define la enseñanza y la dirección de límites/aumentos. El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Sistema de profesiones</a> define descubrimiento artesanal, intercambio de conocimiento, maestría manual, producción por lotes, encargos y reputación multidimensional. Aquí no se redefinen esas reglas de forma independiente. La <a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html">especificación de calidad</a> define el rango compartido de resultados y las propiedades raras de objetos.</p><h2 id="related-skills-and-field-interactions" tabindex="-1">Habilidades relacionadas e interacciones en expediciones <a class="header-anchor" href="#related-skills-and-field-interactions" aria-label="Enlace permanente a &quot;Habilidades relacionadas e interacciones en expediciones&quot;">​</a></h2><p>Lockpicking vence cerraduras mientras Tinkering las comprende/construye; juntos aportan una comprensión más rica. Detect Hidden y Remove Trap pueden apoyar las respuestas al robo. Alchemy aporta candidatos para cargas/energía/lubricantes; Blacksmithing, armazones; Carpentry, estructuras; y Magery/Inscription futuros pueden aportar control solo si se acepta.</p><p><a href="/Syrolands-Public/es/game-design/professions/alchemy.html">Alchemy</a> · <a href="/Syrolands-Public/es/game-design/professions/blacksmithing.html">Blacksmithing</a> · <a href="/Syrolands-Public/es/game-design/professions/carpentry.html">Carpentry</a> · <a href="/Syrolands-Public/es/game-design/magic.html">Magery e Inscription</a> · <a href="/Syrolands-Public/es/game-design/living-world.html#protection-and-regeneration">Protección y regeneración</a>.</p><h2 id="abstraction-and-technical-boundary" tabindex="-1">Abstracción y límite técnico <a class="header-anchor" href="#abstraction-and-technical-boundary" aria-label="Enlace permanente a &quot;Abstracción y límite técnico&quot;">​</a></h2><p>Conservar únicamente estados y respuestas que sustenten decisiones significativas. Se aplican las <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#performance-abstraction-and-authority">restricciones compartidas de abstracción/autoridad</a> y la arquitectura del mundo vivo; la persistencia requiere un diseño técnico separado. Nada de esto selecciona ID de paquetes, esquemas, temporizadores, recursos de interfaz ni algoritmos de ejecución.</p><h2 id="open-questions" tabindex="-1">Preguntas abiertas <a class="header-anchor" href="#open-questions" aria-label="Enlace permanente a &quot;Preguntas abiertas&quot;">​</a></h2><p>Límites de cadenas lógicas, temporizadores y mecanismos activos; permisos de vivienda y pérdidas por robo; trampas, detección, alarmas y respuestas; pérdidas y conocimiento de ingeniería inversa; control, costes y persistencia de constructos. Los gólems siguen siendo una dirección de alto nivel sin recetas, estadísticas, IA ni sistema elegido de vinculación mágica.</p><p>El <a href="/Syrolands-Public/es/game-design/professions/profession-system.html#open-questions-and-reconciliation-required">registro compartido de conciliación</a> define los conflictos entre sistemas. Los experimentos y evidencias existentes de combate no validan este rediseño profesional.</p><h2 id="proposed-training-facilities-—-batch-05" tabindex="-1">Instalaciones de entrenamiento — Propuesto — Batch 05 <a class="header-anchor" href="#proposed-training-facilities-—-batch-05" aria-label="Enlace permanente a &quot;Instalaciones de entrenamiento — Propuesto — Batch 05&quot;">​</a></h2><p>La <a href="/Syrolands-Public/es/game-design/characters/familiarity.html#training-facilities-and-crafts">Familiarity compartida y las instalaciones</a> considera muñecos fabricados, objetivos articulados/móviles, mecanismos de campo de tiro y focos de práctica mágica, con Carpentry, Tinkering e Inscription como posibles participantes. Aquí no se asignan funciones/recetas. Las instalaciones deberían mantener la fluidez de forma eficiente, sin convertirse en el método óptimo para subir habilidades principales ni evitar el descubrimiento.</p>',55)])])}const g=a(r,[["render",o]]);export{u as __pageData,g as default};
